package net.officefloor.hq.app.plan;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Bind the body and refuse it before anything is read: a signed-in user. */
public class ValidatePlanPause {
    public void validate(@RequestBody PlanPauseRequest request, Out<PlanPauseRequest> body) throws InvalidPlanException {
        if (request == null || request.user() == null || request.user().isBlank()) {
            throw new InvalidPlanException("Sign in before pausing or resuming plans.");
        }
        body.set(new PlanPauseRequest(request.user().trim()));
    }
}
== PlanPause
package net.officefloor.hq.app.plan;

import java.time.LocalDate;

/** A pause of a plan: from the day it was paused to the day it was resumed (null while still paused). */
public record PlanPause(LocalDate pausedOn, LocalDate resumedOn) {

    /** Whether the plan date falls in the pause: on or after the day paused and before the day resumed. */
    public boolean skips(LocalDate date) {
        return !date.isBefore(pausedOn) && (resumedOn == null || date.isBefore(resumedOn));
    }
}
