# Every plan on the sheet, in the order they were added, each with how many claims it has made so far. 404 for an id
# never loaded.
load:
  class: net.officefloor.hq.app.sheet.LoadSheet
  govern: [ readonly-transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.plan.RespondWithPlans
  govern: [ readonly-transaction ]
package net.officefloor.hq.app.plan;

import java.util.List;
import java.time.LocalDate;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;

/** Every plan on the sheet, in the order they were added, each with its next dates after the sheet's today. */
public class RespondWithPlans {
    public void respond(@PathVariable("sheetId") String sheetId, PlanRepository repository, SheetRepository sheets,
            ObjectResponse<List<PlanResponse>> response) {
        LocalDate today = sheets.today(sheetId.trim());
        response.send(repository.list(sheetId.trim()).stream().map(p -> PlanResponse.from(p, today)).toList());
    }
}
package net.officefloor.hq.app.plan;

import java.time.LocalDate;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Resume the loaded plan from the sheet's today. Refused when the plan is not paused, or the sheet has no today. */
public class SavePlanResume {
    public void save(@Val PlanPauseRequest input, @Val Plan loaded, SheetRepository sheets, PlanRepository repository,
            Out<PlanResponse> saved) throws InvalidPlanException {
        LocalDate today = sheets.today(loaded.sheetId());
        if (today == null) {
            throw new InvalidPlanException("Set the sheet's today before resuming a plan.");
        }
        if (!repository.resume(loaded.id(), today, input.user())) {
